Import ListNotations.
Open Scope Z_scope.
Set Warnings "-notation-for-abbreviation".
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.

Ltac zto pc := repeat (lazymatch goal with |- evt _ _ (MS _ _ (Z_to_bv 64 pc) _ _ _ _) => fail | _ => zstep end).

Section CANSEC1. Context {rc : runConstT}.
Section Y4F2.
  Variables (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32) (m0 : fmem).
  Variables (DST dcap SS DT lo : Z) (src : list Z) (cells : list deltX2) (cbs : list byte).
  Notation SP := (bv_unsigned sp).
  Notation n := (zlen src).
  Notation seg := ((dcap + 3) / 4).
  Hypothesis TOK : x2_table_ok cells 11.
  Hypothesis ECB : cbs = firstn (Z.to_nat (4 * 2^11)) (x2_bytes' cells).
  Hypothesis LCB : zlen cbs = 8192.
  Hypothesis D8 : 8 <= DST.
  Hypothesis DC : 0 < dcap < 2^32.
  Hypothesis SG : 3 * seg < dcap.
  Hypothesis DL : DST + dcap <= lo.
  Hypothesis S0 : 16 <= SS.
  Hypothesis SL : SS + n <= lo.
  Hypothesis NSM : n < 2^26.
  Hypothesis BYS : Forall (fun c => 0 <= c < 256) src.
  Hypothesis DT0 : 0 < DT.
  Hypothesis CBL : DT + 4 + 8192 <= lo.
  Hypothesis DJ1 : DT + 4 + 8192 <= DST \/ DST + dcap <= DT.
  Hypothesis DJ3 : DST + dcap <= SS \/ SS + n <= DST.
  Hypothesis LOS : lo <= SP - 4096.
  Hypothesis SP16 : SP mod 16 = 0.
  Hypothesis SP47 : SP <= 2^47.

  Notation DW := [(SP - 4096, SP); (DST, DST + dcap)].
  Notation POST := (huf_dec_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc DST dcap lo m0).
  Notation FRS := [C8 s11; C8 s10; C8 s9; C8 s8; C8 s7; C8 s6; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra].
  Notation Y4M := (RF_huf_y4fast.Y4M ra sp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 m0 DST dcap SS DT lo src cbs).
  Notation SPS := (RF_huf_y4fast.SPS DST dcap SS DT src).

  Notation YF l := (l ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m0 DST dcap SS DT lo src cells cbs
                      TOK ECB LCB D8 DC SG DL S0 SL NSM BYS DT0 CBL DJ1 DJ3 LOS SP16 SP47) (only parsing).

  Ltac y4pack OUT LB :=
    split; [eexists; split; [exact OUT| rewrite ?Zupd_length; exact LB]|];
    split; [eassumption|]; split; [eassumption|]; split; [eassumption|];
    split; [eexists; eassumption|];
    repeat (split; [eassumption|]); eassumption.

  Section STREAM2.
  Variables (k SE OPk DBC : Z) (ws : list word).
  Hypothesis K4 : 0 <= k < 4.
  Hypothesis HSE : DST <= OPk <= SE.
  Hypothesis HSE2 : SE <= DST + dcap.
  Hypothesis WOP : nth_error ws (Z.to_nat (4 + k)) = Some (Z_to_bv 64 OPk).

  Notation ST pc mm x9 a1 a2 a3 x18 x19 x20 x24 x25 x26 x27 :=
    (MS (mkR (Z_to_bv 64 (SP + -192)) (Z_to_bv 64 (SP + -416)) gp tp (Z_to_bv 64 8) (Z_to_bv 64 k) (Z_to_bv 64 seg)
             (Z_to_bv 64 (SP + -224 + 8 * k)) x9 (Z_to_bv 64 (DT + 4)) a1 a2 a3 (Z_to_bv 64 0x104d0)
             (Z_to_bv 64 (SP + -136)) (Z_to_bv 64 (SP + -256)) (Z_to_bv 64 DBC) x18 x19 x20 (Z_to_bv 64 OPk)
             (Z_to_bv 64 SS) (Z_to_bv 64 (SS + 8)) x24 x25 x26 x27 (Z_to_bv 64 64) (Z_to_bv 64 2) (Z_to_bv 64 4) (Z_to_bv 64 SE))
        F (Z_to_bv 64 pc) fc None mm (seg_rom psegs)).

  Hypothesis CONT : forall mm (x9 a2 a3 x18 x19 x20 x24 x25 x26 x27 : word),
    Y4M mm SPS (upd ws (Z.to_nat (4 + k)) (Z_to_bv 64 SE)) ->
    evt psegs POST (ST 0x15f18 mm x9 (Z_to_bv 64 SE) a2 a3 x18 x19 x20 x24 x25 x26 x27).

  Notation YS l := (YF l k SE OPk DBC ws K4 HSE HSE2 WOP CONT) (only parsing).

  (* [comment removed for export] *)
  Ltac y4cell v :=
    lazymatch goal with |- context [Z.land (((bv_unsigned ?c ≪ ?b) mod 18446744073709551616) ≫ 51) 18446744073709551612] =>
      rewrite (y4_land_m4_shr ((bv_unsigned c ≪ b) mod 18446744073709551616)) by (apply Z.mod_pos_bound; lia);
      let EV := fresh "EV" in let VR := fresh "VR" in
      pose proof (y4_shr53_bound ((bv_unsigned c ≪ b) mod 18446744073709551616) ltac:(apply Z.mod_pos_bound; lia)) as VR;
      remember (((bv_unsigned c ≪ b) mod 18446744073709551616) ≫ 53) as v eqn:EV; clear EV end.
  Ltac y4c v c EC :=
    lazymatch goal with TCK : forall i, 0 <= i < 2^11 -> _, VR : 0 <= v < 2048 |- _ =>
      remember (nth (Z.to_nat v) cells x2_default) as c eqn:EC;
      let SQ := fresh "SQ" in let NB := fresh "NB" in let LN := fresh "LN" in
      destruct (TCK v ltac:(change (2^11) with 2048; exact VR)) as (SQ & NB & LN); rewrite <- EC in SQ, NB, LN end.
  Ltac y4rd v c EC :=
    lazymatch goal with CE : bytes_at psegs ?mm (DT + 4) cbs, SQ : 0 <= x2_seq c < 65536 |- _ =>
      let RC0 := fresh "RC" in let RC2 := fresh "RC" in let RC3 := fresh "RC" in let RCB := fresh "RC" in
      destruct (x2_cell_rd psegs mm (DT + 4) cells (Z.to_nat (4 * 2^11)) v c ltac:(rewrite <- ECB; exact CE)
                  ltac:(lia) ltac:(lia) ltac:(lia) EC SQ) as (RC0 & RC2 & RC3 & RCB) end.

  (* [comment removed for export] *)
  Ltac y4d OUT v c EC i padd :=
    zstep; zstep; zstep; y4cell v; zstep;
    y4c v c EC; y4rd v c EC;
    zstep; (lazymatch padd with true => zstep | false => idtac end);
    zstep; unfold sx16;
    u8_sok OUT i; zstep; u8_store_same OUT i;
    u8_sok OUT (i + 1); zstep; u8_store_same OUT (i + 1);
    y4rd v c EC;
    zstep; zstep; rewrite ?(byte_lit (x2_nbBits c)), ?(byte_lit (x2_len c)) by lia;
    zstep.

