    (forall p' bits' mm' (x9' x19' x24' : word), Y4M mm' SPS ws -> p + 5 <= p' <= p + 10 -> 0 <= bits' <= 119 ->
       evt psegs POST (ST 0x15cb8 mm' x9' a1 (Z_to_bv 64 bits') (Z_to_bv 64 (SE - 9)) (Z_to_bv 64 p') x19' x20 x24' x25 x26 x27)) ->
    evt psegs POST (ST 0x15bc8 mm x9 a1 (Z_to_bv 64 bits) (Z_to_bv 64 (SE - 9)) (Z_to_bv 64 p) x19 x20 x24 x25 x26 x27).
